-- Elkhorn Resort: client and its two report templates.
-- Run once in Supabase → SQL Editor, after portal-setup.sql.
-- Budget "opening spend" = year-to-date spend through September 2026.

do $$
declare
  client_id uuid;
begin
  if exists (select 1 from public.portal_clients where name = 'Elkhorn Resort') then
    raise notice 'Elkhorn Resort already exists, skipping.';
    return;
  end if;

  insert into public.portal_clients (name, brand_color, logo_data)
  values ('Elkhorn Resort', '#0B6B57', 'data:image/png;base64,')
  returning id into client_id;

  insert into public.portal_templates (client_id, name, cadence, schema) values
    (client_id, 'Weekly Marketing Report', 'weekly', '{"periodLabel":"For the week of","sections":[{"id":"overview","type":"stats","title":"Marketing Overview","fields":[{"id":"fb_posts","label":"Facebook Posts","format":"number"},{"id":"ig_posts","label":"Instagram Posts","format":"number"},{"id":"fb_views","label":"Facebook Post Views","format":"compact","compare":true},{"id":"ig_views","label":"Instagram Post Views","format":"compact","compare":true},{"id":"fb_followers","label":"Facebook Followers","format":"number","compare":true,"trend":true},{"id":"ig_followers","label":"Instagram Followers","format":"number","compare":true,"trend":true}]},{"id":"posts","type":"table","title":"Social Media Posts","numberLabel":"Post","emptyText":"No posts this week.","columns":[{"id":"type","label":"Type of Post","format":"text"},{"id":"platform","label":"Platform","format":"text","options":["Instagram & Facebook","Instagram","Facebook"]},{"id":"views","label":"Views","format":"number","total":true}]},{"id":"page_views","type":"stats","title":"Page Views","fields":[{"id":"fb_7","label":"Facebook · past 7 days","format":"change"},{"id":"ig_7","label":"Instagram · past 7 days","format":"change"},{"id":"fb_28","label":"Facebook · past 28 days","format":"change"},{"id":"ig_28","label":"Instagram · past 28 days","format":"change"}]},{"id":"emails_sent","type":"table","title":"Email Blasts Sent","emptyText":"No emails were sent this week.","columns":[{"id":"date","label":"Date Sent","format":"date"},{"id":"content","label":"Email Content","format":"text"},{"id":"open_rate","label":"Open Rate","format":"percent"},{"id":"ctr","label":"Click-Through Rate","format":"percent"}]},{"id":"emails_upcoming","type":"table","title":"Upcoming Email Blasts","carryOver":true,"emptyText":"No emails scheduled yet.","columns":[{"id":"date","label":"Date to Be Sent","format":"date"},{"id":"content","label":"Email Content","format":"text"}]}]}'::jsonb),
    (client_id, 'Digital Marketing Ad Report', 'monthly', '{"periodLabel":"Reporting period","sections":[{"id":"ads","type":"ads","title":"Ad Report & Overview","carryOver":true,"channels":[{"id":"social","name":"Social Media Ads","metricLabel":"Link/Ad Clicks"},{"id":"youtube","name":"YouTube Ads","metricLabel":"Engagements"},{"id":"google","name":"Google Ads","metricLabel":"Link Clicks"}]},{"id":"seo","type":"text","title":"Search Engine Optimization","placeholder":"Tasks completed this month…"},{"id":"budget","type":"budget","title":"Ad Budget Overview & Status","year":2026,"lines":[{"id":"social","label":"Social Media Ads","annualBudget":36000,"openingSpend":26890.5,"source":{"kind":"channel","sectionId":"ads","channelId":"social"}},{"id":"youtube","label":"YouTube Ads","annualBudget":24000,"openingSpend":17949.75,"source":{"kind":"channel","sectionId":"ads","channelId":"youtube"}},{"id":"google","label":"Google Ads","annualBudget":12000,"openingSpend":8968.05,"source":{"kind":"channel","sectionId":"ads","channelId":"google"}},{"id":"seo","label":"Search Engine Optimization","annualBudget":12000,"openingSpend":9000,"source":{"kind":"manual"}}]},{"id":"notes","type":"text","title":"General Notes & Comments","placeholder":"Highlights, website traffic, what''s next…"}]}'::jsonb);
end $$;
